class Solution:
    def isMonotonic(self, nums: List[int]) -> bool:
        counter = 0
        for i in range(len(nums) - 1):
            if nums[i] >= nums[i + 1]:
                counter += 1
        if counter == len(nums) - 1:
            return True
        counter = 0
        for i in range(len(nums) - 1):
            if nums[i] <= nums[i + 1]:
                counter += 1
        if counter == len(nums) - 1:
            return True
        return False

class Solution:
    def isMonotonic(self, A):
        inc, dec = False, False
        for i in range(len(A)-1):
            if A[i] < A[i+1]:
                inc = True
            elif A[i] > A[i+1]:
                dec = True
        return not inc or not dec

class Solution:
    def subarrayBitwiseORs(self, A):
        result, curr = set(), {0}
        for i in A:
            curr = {i} | {i | j for j in curr}
            result |= curr
        return len(result)

